// Frontend company logo assets - statically bundled, zero backend storage needed

export const ISMARTU_LOGO_SRC = 'data:image/png;base64,'
export const PADGET_LOGO_SRC = 'data:image/png;base64,'

export function getCompanyLogo(company?: string): { src: string; alt: string; isPadget: boolean } {
  const norm = (company || '').trim().toLowerCase()
  const isPadget = norm.includes('padget')
  return {
    src: isPadget ? PADGET_LOGO_SRC : ISMARTU_LOGO_SRC,
    alt: isPadget ? 'PadGET' : 'ismartu',
    isPadget,
  }
}
